import{c as i,Z as o,Q as n,j as l,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"四块玉·别情","description":"","frontmatter":{"title":"四块玉·别情","author":"关汉卿","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/4.md","filePath":"books/shici/yuanqu/4.md"}'),u={name:"books/shici/yuanqu/4.md"};function h(c,a,d,p,q,_){const e=o("PoemAuthor"),r=o("PoemNav");return n(),l("div",null,[a[0]||(a[0]=s('<h1 id="四块玉·别情" tabindex="-1">四块玉·别情 <a class="header-anchor" href="#四块玉·别情" aria-label="Permalink to &quot;四块玉·别情&quot;">​</a></h1><p><strong>[元] <a href="/authors/guanhanqing.html">关汉卿</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>自送别，心难舍，一点相思几时绝？ 凭阑袖拂杨花雪。 溪又斜，山又遮，人去也！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>四块玉：曲牌名</li><li>心难舍：心中难以割舍</li><li>几时绝：何时才能断绝</li><li>凭阑：倚靠栏杆</li><li>袖拂杨花雪：用衣袖拂去如雪花般飞舞的杨花</li><li>杨花雪：杨花像雪一样飘飞</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>自从送别你之后，心中难以割舍，这一点相思之情何时才能断绝？ 倚着栏杆，用衣袖拂去那如雪花般飞舞的杨花。 溪水蜿蜒曲折，青山重重遮挡，你早已远去，看不见了！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是关汉卿描写离别相思的名作，语言质朴自然，感情真挚动人。</p><p>&quot;自送别，心难舍，一点相思几时绝？&quot;开篇直抒胸臆，写送别后难以割舍的思念之情。&quot;一点相思几时绝&quot;以问句出之，将相思的绵长与无奈表现得淋漓尽致。</p><p>&quot;凭阑袖拂杨花雪&quot;一句，以景衬情。杨花纷飞如雪，既点明暮春时节，又象征离情的纷乱与漂泊。主人公凭阑远望，频频拂袖，既是为了拂去迷眼的杨花，更是为了张望那已远去的行人。</p><p>&quot;溪又斜，山又遮，人去也！&quot;三句，写视线被溪水、青山层层阻隔，行人终于消失在远方。&quot;人去也&quot;三字，如一声长叹，将离别时的怅惘与失落推向高潮。全曲由情入景，由景结情，言有尽而意无穷。</p>',13)),t(e,{name:"关汉卿",years:"约1234年－约1300年",desc:"号已斋叟，元代著名戏曲作家，元曲四大家之首。其散曲风格清新自然，多写男女爱情。",link:"/authors/guanhanqing"}),t(r)])}const b=i(u,[["render",h]]);export{f as __pageData,b as default};
